private static JsonNode awaitTranscript(
        java.net.http.HttpClient client, int port, String sessionId, int size) throws Exception {
    long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
    while (true) {
        var response = client.send(java.net.http.HttpRequest.newBuilder(java.net.URI.create(
                "http://127.0.0.1:" + port + "/api/v1/sessions/" + sessionId + "/snapshot"))
                .GET().build(), java.net.http.HttpResponse.BodyHandlers.ofString());
        JsonNode snapshot = MAPPER.readTree(response.body());
        if (snapshot.path("transcript").size() >= size) return snapshot;
        if (System.nanoTime() >= deadline) throw new AssertionError("snapshot did not complete: " + snapshot);
        Thread.sleep(10);
    }
}

